mapper.select:
SELECT d.id, d.device_id, d.metric_key, d.metric_value, d.record_time, d.quality_flag, d.source_type, d.operator_id, dev.device_sn, dev.device_name, t.type_name FROM iot_ts_data d LEFT JOIN iot_device dev ON d.device_id = dev.id LEFT JOIN iot_device_type t ON dev.type_id = t.id
AND d.device_id = #{query.deviceId}
AND dev.device_sn LIKE CONCAT('%', #{query.deviceSn}, '%')
AND d.metric_key = #{query.metricKey}
AND d.record_time >= #{query.startTime}
AND d.record_time <= #{query.endTime}
AND d.source_type = #{query.sourceType}
AND d.quality_flag = #{query.qualityFlag}
ORDER BY d.record_time DESC

SELECT d.id, d.device_id, d.metric_key, d.metric_value, d.record_time, d.quality_flag, d.source_type, d.operator_id, dev.device_sn, dev.device_name, t.type_name FROM iot_ts_data d INNER JOIN ( SELECT device_id, metric_key, MAX(record_time) AS max_time FROM iot_ts_data
AND device_id = #{query.deviceId}
AND metric_key = #{query.metricKey}
GROUP BY device_id, metric_key ) latest ON d.device_id = latest.device_id AND d.metric_key = latest.metric_key AND d.record_time = latest.max_time LEFT JOIN iot_device dev ON d.device_id = dev.id LEFT JOIN iot_device_type t ON dev.type_id = t.id ORDER BY d.device_id, d.metric_key
